// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 val) internal {
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        vm.assume(before == 0);
        bool reverted;
        try c.SetMinSum(val) { reverted = false; } catch { reverted = true; }
        assertTrue((!reverted && c.MinSum() == val) || (reverted && c.MinSum() == before));
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
